import sys

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0])
    words = data[1:n+1]

    max_length = 0

    # Try all pairs of letters (a-z)
    for c1 in range(26):
        for c2 in range(26):
            if c1 == c2:
                # Single letter case
                valid_words = [word for word in words if all(ch == chr(c1+97) for ch in word)]
            else:
                # Two distinct letters case
                valid_words = [word for word in words if all(ch == chr(c1+97) or ch == chr(c2+97) for ch in word)]

            total_length = sum(len(word) for word in valid_words)

            if total_length > max_length:
                max_length = total_length

    print(max_length)

if __name__ == "__main__":
    solve()
"}

