n, m = map(int, input().split())
a = list(map(int, input().split()))

# Count occurrences of each value in the entire array
from collections import defaultdict
value_counts = defaultdict(int)
for num in a:
    value_counts[num] += 1

# Create prefix sums for each unique value
prefix_sums = {}
for val, _ in value_counts.items():
    # Create a sorted list of indices where this value appears
    indices = []
    for i, num in enumerate(a):
        if num == val:
            indices.append(i + 1)  # 1-indexed
    prefix_sums[val] = indices

# Process each query
for _ in range(m):
    l, r = map(int, input().split())

    count = 0
    for val, indices in prefix_sums.items():
        # Use binary search to find how many times val appears in [l, r]
        left = bisect.bisect_left(indices, l)
        right_idx = bisect.bisect_right(indices, r)
        occurrences = right_idx - left

        if occurrences == val:
            count += 1

    print(count)
"}

