import sys

def solve() -> None:
    data = sys.stdin.read().strip().split('\n')

    if not data:
        return

    n = int(data[0])

    if n == 1:
        print(-1)
        return

    directions = data[1].strip()
    positions = list(map(int, data[2].strip().split()))

    min_time = float('inf')

    for i in range(n - 1):
        if directions[i] == 'R' and directions[i + 1] == 'L':
            time = (positions[i + 1] - positions[i]) // 2
            min_time = min(min_time, time)

    if min_time == float('inf'):
        print(-1)
    else:
        print(min_time)

if __name__ == "__main__":
    solve()
"}

