import sys

def count_vk(s):
    """Count number of "VK" substrings in s."""
    return sum(1 for i in range(len(s) - 1) if s[i] == 'V' and s[i + 1] == 'K')

def solve():
    s = sys.stdin.readline().strip()
    max_count = count_vk(s)

    n = len(s)
    if n == 1:
        return max_count

    for i in range(n):
        # Try changing s[i] to 'V'
        t = list(s)
        t[i] = 'V'
        cnt = count_vk(t)
        if cnt > max_count:
            max_count = cnt
        # Try changing s[i] to 'K'
        t[i] = 'K'
        cnt = count_vk(t)
        if cnt > max_count:
            max_count = cnt

    return max_count

if __name__ == '__main__':
    result = solve()
    sys.stdout.write(str(result) + '\n')
"}

