n, m = map(int, input().split())

poland = set()
for _ in range(n):
    poland.add(input().strip())

enemy = set()
for _ in range(m):
    enemy.add(input().strip())

# Count unique words
u1 = len(poland - enemy)  # unique to PolandBall
u2 = len(enemy - poland)  # unique to EnemyBall

# Count shared words
shared = poland & enemy
s1 = len(shared)
s2 = len(shared)  # both have the same shared words

if u1 > u2:
    print("YES")
elif u1 < u2:
    print("NO")
else:
    # If unique counts are equal, more shared words means more turns
    if s1 > s2:
        print("YES")
    elif s1 < s2:
        print("NO")
    else:
        # If both have the same number of shared words, PolandBall starts first and loses
        print("NO")
"}

