import sys
import math

def smallest_prime_factor(n):
    """Return the smallest prime factor of n"""
    if n % 2 == 0:
        return 2
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return i
    return n

def solve():
    n = int(sys.stdin.readline())

    # Find all smallest prime factors for numbers from 2 to n
    spf = [0] * (n + 1)
    for i in range(2, n + 1):
        if spf[i] == 0:
            spf[i] = i
            for j in range(i * i, n + 1, i):
                if spf[j] == 0:
                    spf[j] = i

    # Assign colors
    colors = [0] * (n + 1)
    color_count = 1
    for i in range(2, n + 1):
        if spf[i] == i:  # i is prime
            colors[i] = color_count
            color_count += 1
        else:
            colors[i] = colors[spf[i]]

    # Output results for 2 to n
    output = [str(colors[i]) for i in range(2, n + 1)]
    sys.stdout.write(" ".join(output))

if __name__ == "__main__":
    solve()
"}

