import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n, x, y = map(int, data[0:3])
    number = data[3]

    # Target: number % 10^x == 10^y
    # This means last x digits should be exactly 10^y
    # 10^y has y zeros followed by a 1, so:
    # - Position (n-1-x+y) should be 1
    # - All other positions in the last x should be 0

    target_pos = n - 1 - x + y

    # Count operations needed
    operations = 0

    # Check all positions in the last x
    for i in range(target_pos, target_pos + x):
        if i < len(number):
            if i == target_pos:
                # This position should be 1
                if number[i] == '0':
                    operations += 1
            else:
                # All other positions should be 0
                if number[i] == '1':
                    operations += 1
        else:
            # This shouldn't happen since n > x
            pass

    print(operations)

if __name__ == "__main__":
    solve()
"}

