t = int(input())
for _ in range(t):
    a = input().strip()
    b = input().strip()

    if a == b:
        print(0)
        continue

    operations = []
    n = len(a)

    # Try to transform a into b
    for i in range(n // 2):
        if a[i] != b[i]:
            # Find where b[i] is
            for j in range(n):
                if a[j] == b[i]:
                    # Move b[i] to position i
                    # Reverse a prefix of length 2*min(i, j)+2
                    operations.append(2 * min(i, j) + 2)

                    # Now b[i] is at position min(i, j)+1
                    # Swap them back
                    operations.append(2 * min(i, j) + 2)
                    break

    # Check if we're done
    if a == b:
        print(len(operations))
        print(' '.join(map(str, operations)))
    else:
        print(-1)
"}

