# Try all possible lengths from 1 to min(n, m)
for L in range(1, min(n, m) + 1):
    # Find all substrings of A of length L
    substrings_A = set()
    for i in range(n - L + 1):
        substrings_A.add(A[i:i+L])

    # Find all substrings of B of length L
    substrings_B = set()
    for j in range(m - L + 1):
        substrings_B.add(B[j:j+L])

    # Check all pairs of substrings of length L
    for substr_A in substrings_A:
        for substr_B in substrings_B:
            # Calculate LCS
            # Since substrings are of the same length L, LCS can be found by checking character by character
            lcs = 0
            i = 0
            j = 0
            while i < L and j < L:
                if substr_A[i] == substr_B[j]:
                    lcs += 1
                    i += 1
                    j += 1
                else:
                    if substr_A[i] < substr_B[j]:
                        i += 1
                    else:
                        j += 1

            score = 4 * lcs - L - L
            if score > max_score:
                max_score = score

print(max_score)
