def solve_berland_problem():
    n, m = map(int, input().split())

    # Create matrix: rows are roads, columns are cities
    matrix = []
    for _ in range(m):
        a, b, c = map(int, input().split())
        row = [0] * n
        row[a-1] = 1
        row[b-1] = 1
        matrix.append(row)

    # Target: all roads should be asphalted (all 1s)
    target = [1] * m

    # Gaussian elimination over GF(2)
    rank = 0
    solution = [0] * n

    for col in range(n):
        # Find pivot
        pivot_row = -1
        for r in range(rank, m):
            if matrix[r][col] == 1:
                pivot_row = r
                break

        if pivot_row == -1:
            continue

        # Swap pivot row with current rank row
        matrix[rank], matrix[pivot_row] = matrix[pivot_row], matrix[rank]
        target[rank], target[pivot_row] = target[pivot_row], target[rank]

        # Eliminate this column in other rows
        for r in range(m):
            if r != rank and matrix[r][col] == 1:
                for c in range(col, n):
                    matrix[r][c] ^= matrix[rank][c]
                target[r] ^= target[rank]

        rank += 1

    # Check if solution is possible
    for r in range(rank, m):
        if target[r] == 1:
            print("Impossible")
            return

    # Back substitution
    for col in range(n):
        for r in range(rank):
            if matrix[r][col] == 1 and solution[col] == 0:
                solution[col] = 1
                for c in range(col + 1, n):
                    matrix[r][c] ^= matrix[col][c]
                target[r] ^= target[col]

    # Output solution
    print(rank)
    print(' '.join(str(i+1) for i in range(n) if solution[i]))

solve_berland_problem()
