for move in s1:
    for pos in range(1, n + 1):
        next_pos = (pos + move) % n
        if next_pos == 0:
            next_pos = n
        adj_rick[pos].append(next_pos)

for move in s2:
    for pos in range(1, n + 1):
        next_pos = (pos + move) % n
        if next_pos == 0:
            next_pos = n
        adj_morty[pos].append(next_pos)

# result[pos][turn] = "Win", "Lose", or "Loop"
# turn = 0 for Rick, 1 for Morty
result = [[None] * 2 for _ in range(n + 1)]

# Position 1 is the black hole - if we reach it, the previous player won
result[1][0] = "Win"
result[1][1] = "Win"

# Work backwards from position 1 to position n
for pos in range(n, 0, -1):
    if pos == 1:
        continue

    # Check all positions that can reach this position in one move
    # For Rick's turn
    for prev_pos in range(1, n + 1):
        if result[prev_pos][0] is None:
            continue

        # Check if Rick can move to this position
        if prev_pos in adj_rick:
            next_pos_list = adj_rick[prev_pos]
            if any(next_pos == pos for next_pos in next_pos_list):
                # Rick can move to this position
                if result[pos][1] is None:
                    result[pos][1] = "Win"
                else:
                    result[pos][1] = "Lose"

    # For Morty's turn
    for prev_pos in range(1, n + 1):
        if result[prev_pos][1] is None:
