            if any(next_pos == pos for next_pos in next_pos_list):
                # Morty can move to this position
                if result[pos][0] is None:
                    result[pos][0] = "Win"
                else:
                    result[pos][0] = "Lose"

# Output results for Rick first (positions 2 to n)
