def solve():
    n = int(input())
    grid = []
    normal_cells = []
    evil_cells = []

    for i in range(n):
        row = input().strip()
        grid.append(row)

        for j, cell in enumerate(row):
            if cell == '.':
                normal_cells.append((i, j))
            elif cell == 'E':
                evil_cells.append((i, j))

    if not normal_cells and evil_cells:
        print(-1)
        return

    # Check if it's possible to purify all evil cells
    possible = True
    for x, y in evil_cells:
        # Check if there's a normal cell in row x or column y
        has_normal = False
        for j in range(n):
            if grid[x][j] == '.':
                has_normal = True
                break
        if not has_normal:
            for i in range(n):
                if grid[i][y] == '.':
                    has_normal = True
                    break
        if not has_normal:
            possible = False
            break

    if not possible:
        print(-1)
        return

    # Now find a minimum set of normal cells to cover all evil cells
    # We can just output all normal cells, or use a greedy approach
    selected = []
    remaining_evil = evil_cells.copy()

    while remaining_evil:
        best_cell = None
        best_cover = 0

        for cell in normal_cells:
            i, j = cell
            # Calculate cells covered by selecting (i, j)
            covered = []
            for evil in remaining_evil:
                x, y = evil
                if x == i or y == j:
                    covered.append(evil)

            if len(covered) > best_cover:
                best_cover = len(covered)
                best_cell = cell

        if best_cover == 0:
            # No cell covers any remaining evil cells
            print(-1)
            return

        selected.append(best_cell)
        remaining_evil = [cell for cell in remaining_evil if cell not in covered]

    print(len(selected))
    for i, j in selected:
        print(i + 1, j + 1)

solve()
