    data = sys.stdin.read().strip().split()
    if not data:
        return

    ptr = 0
    n = int(data[ptr])
    ptr += 1
    m = int(data[ptr])
    ptr += 1

    regions = {}
    for _ in range(n):
        surname = data[ptr]
        ptr += 1
        region = int(data[ptr])
        ptr += 1
        score = int(data[ptr])
        ptr += 1

        if region not in regions:
            regions[region] = []
        regions[region].append((surname, score))

    # For each region, process
    for region in sorted(regions.keys()):
        participants = regions[region]
        participants.sort(key=lambda x: -x[1])  # sort by score descending
        k = len(participants)

        valid_teams = []
        for i in range(k):
            for j in range(i + 1, k):
                # Check if participants[i] and participants[j] are both irreplaceable
                s1, score1 = participants[i]
                s2, score2 = participants[j]
                score_max = max(score1, score2)

                # Check if there's any participant not in the team with score > score1
                replaceable1 = False
                for idx in range(k):
                    if idx == i or idx == j:
                        continue
                    if participants[idx][1] > score1:
                        replaceable1 = True
                        break

                # Check if there's any participant not in the team with score > score2
                replaceable2 = False
                for idx in range(k):
                    if idx == i or idx == j:
                        continue
                    if participants[idx][1] > score2:
                        replaceable2 = True
                        break

                if not replaceable1 and not replaceable2:
                    valid_teams.append((s1, s2))

        if len(valid_teams) == 1:
            print(f"{valid_teams[0][0]} {valid_teams[0][1]}")
        else:
            print("?\n")

