def is_permutation(compression, m):
    """Check if compression is a permutation of [1, 2, ..., m]"""
    return len(compression) == m and len(set(compression)) == m and max(compression) == m and min(compression) == 1

def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        result = []
        for k in range(1, n + 1):
            # Compute k-compression
            compression = []
            for i in range(n - k + 1):
                window = a[i:i+k]
                compression.append(min(window))

            m = n - k + 1
            if is_permutation(compression, m):
                result.append('1')
            else:
                result.append('0')

        results.append(''.join(result))

    print('\n'.join(results))

solve()
