def main():
    n = int(input())
    hostname_paths = defaultdict(set)
    url_to_hostname = {}  # Map from full URL to hostname

    for _ in range(n):
        url = input().strip()
        url_to_hostname[url] = hostname

        # Extract hostname and path
        parts = url.split('://', 1)
        if len(parts) < 2:
            hostname = None  # Invalid URL, skip
        else:
            address_part = parts[1]
            if '/' in address_part:
                hostname, path = address_part.split('/', 1)
            else:
                hostname = address_part
                path = ''

        if hostname is not None:
            hostname_paths[hostname].add(path)

    # Group hostnames by their path sets
    groups = defaultdict(list)
    for hostname, paths in hostname_paths.items():
        sorted_paths = sorted(paths)
        key = tuple(sorted_paths)
        groups[key].append(hostname)

    # Output results
    result = []
    for paths, hostnames in groups.items():
        if len(hostnames) > 1:
            # Get all URLs for these hostnames
            urls = []
            for hostname in hostnames:
                # Find all URLs with this hostname
                host_urls = [url for url, h in url_to_hostname.items() if h == hostname]
                urls.extend(host_urls)
            result.append(' '.join(urls))

    print(len(result))
    for line in result:
        print(line)

