    if not data:
        return

    # Parse input
    parts = data[0].split()
    n = int(parts[0])
    m = int(parts[1])

    # Read participants
    participants = []
    for i in range(1, n + 1):
        line = data[i].split()
        surname = line[0]
        region = int(line[1])
        score = int(line[2])
        participants.append((surname, region, score))

    # Group by region
    regions = {}
    for surname, region, score in participants:
        if region not in regions:
            regions[region] = []
        regions[region].append((surname, score))

    # Process each region
    for region in sorted(regions.keys()):
        # Sort by score descending
        sorted_region = sorted(regions[region], key=lambda x: (-x[1], x[0]))

        # Get top scorer
        top_surname, top_score = sorted_region[0]

        # Get second participant
        if len(sorted_region) >= 2:
            second_surname, second_score = sorted_region[1]
