def solve():
    import sys
    input = sys.stdin.read().split()
    data = list(map(int, input))
    idx = 0
    t = data[idx]
    idx += 1

    def find_centroid(tree, n):
        # Find centroid of the tree
        # We'll use a standard centroid decomposition approach
        # First, compute sizes of subtrees
        size = [0] * (n + 1)
        def dfs_size(u, parent):
            size[u] = 1
            for v in tree[u]:
                if v != parent:
                    dfs_size(v, u)
                    size[u] += size[v]
        dfs_size(1, -1)

        # Find centroid
        def dfs_centroid(u, parent, total_size):
            for v in tree[u]:
                if v != parent and size[v] > total_size // 2:
                    return dfs_centroid(v, u, total_size)
            return u

        return dfs_centroid(1, -1, n)

    for _ in range(t):
        n = data[idx]
        a = data[idx + 1]
        b = data[idx + 2]
        da = data[idx + 3]
        db = data[idx + 4]
        idx += 5

        # Build tree
        tree = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = data[idx]
            v = data[idx + 1]
            idx += 2
            tree[u].append(v)
            tree[v].append(u)

        # Calculate distance between a and b
        def bfs_dist(start, end):
            dist = [-1] * (n + 1)
            dist[start] = 0
            from collections import deque
            q = deque([start])
            while q:
                u = q.popleft()
                for v in tree[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        q.append(v)
                        if v == end:
                            return dist[end]
            return -1

