def solve():
    MOD = 998244353
    n = int(input())
    a = list(map(int, input().split()))

    # Precompute digits of each number (least significant first)
    digits_list = []
    for num in a:
        digits = []
        # Extract digits from least significant to most significant
        temp = num
        while temp > 0:
            digits.append(temp % 10)
            temp //= 10
        digits_list.append(digits)

    total = 0
    # For each pair of numbers
    for i in range(n):
        for j in range(n):
            # Get digits of a_i and a_j
            x_digits = digits_list[i]
            y_digits = digits_list[j]

            # Compute the result f(a_i, a_j)
            result = []
            max_len = max(len(x_digits), len(y_digits))
            for pos in range(max_len):
                if pos < min(len(x_digits), len(y_digits)):
                    if pos % 2 == 0:
                        result.append(y_digits[pos // 2])
                    else:
                        result.append(x_digits[(pos - 1) // 2])
                else:
                    if len(x_digits) > len(y_digits):
                        result.append(x_digits[pos])
                    else:
                        result.append(y_digits[pos])

            # Convert result to integer
            result_num = 0
            for d in result:
