def solve():
    n, k = map(int, input().split())
    grid = [input().strip() for _ in range(n)]

    # DFS with backtracking to find lexicographically smallest path
    def dfs(i, j, changes, path):
        # Check if we've reached the end
        if i == n - 1 and j == n - 1:
            return path

        # Try to move right
        if j + 1 < n:
            # Try to make the next character as small as possible
            for c in range(ord('a'), ord('z') + 1):
                next_char = chr(c)

                # Calculate cost: 0 if we can use existing character, 1 if we need to change
                existing_char = grid[i][j+1]
                cost = 0 if next_char == existing_char else 1

                if changes + cost <= k:
                    result = dfs(i, j+1, changes + cost, path + next_char)
                    if result is not None:
                        return result

        # Try to move down
        if i + 1 < n:
            for c in range(ord('a'), ord('z') + 1):
                next_char = chr(c)
                existing_char = grid[i+1][j]
                cost = 0 if next_char == existing_char else 1

                if changes + cost <= k:
                    result = dfs(i+1, j, changes + cost, path + next_char)
                    if result is not None:
                        return result

        return None

    result = dfs(0, 0, 0, grid[0][0])
    print(result)

