n, m = map(int, input().split())

# Precompute prime factors for all numbers up to n using Sieve of Eratosthenes
prime_factors = [[] for _ in range(n + 1)]
for i in range(2, n + 1):
    if not prime_factors[i]:  # i is prime
        for j in range(i, n + 1, i):
            prime_factors[j].append(i)

activated = set()

for _ in range(m):
    req = input().split()
    op, i = req[0], int(req[1])

    if op == "+":
        if i in activated:
            print("Already on")
        else:
            # Check for conflicts
            conflict = None
            for j in activated:
                # Check if i and j share any prime factor
                # If they share a prime factor, they are not relatively prime
                if set(prime_factors[i]) & set(prime_factors[j]):
                    conflict = j
                    break

            if conflict is not None:
                print(f"Conflict with {conflict}")
            else:
                activated.add(i)
                print("Success")
    else:  # op == "-"
        if i not in activated:
            print("Already off")
        else:
            activated.remove(i)
            print("Success")
"}

