def is_balanced(s):
    """Check if the string has equal number of '(' and ')'"""
    return s.count('(') == s.count(')')


def count_correct_cyclical_shifts(s):
    """Count how many cyclical shifts of s are correct bracket sequences"""
    n = len(s)
    if not is_balanced(s):
        return [0] * n

    counts = [0] * n
    for k in range(n):
        shifted = s[k:] + s[:k]
        balance = 0
        for c in shifted:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                break
        if balance >= 0:
            counts[k] = 1
    return counts


def solve():
    n = int(input().strip())
    s = input().strip()

    # Calculate initial correct cyclical shifts
    correct_counts = count_correct_cyclical_shifts(s)
    max_correct = max(correct_counts)

    # Find the best swap
    best_correct = 0
    best_l, best_r = 0, 0

    # Try all possible swaps
    for i in range(n):
        for j in range(i, n):
            # Swap characters at positions i and j (1-indexed)
            new_s = s[:i] + s[j] + s[i+1:j] + s[i] + s[j+1:]

            # Count correct cyclical shifts after swap
            new_counts = count_correct_cyclical_shifts(new_s)
            new_max = max(new_counts)

            # Update best
            if new_max > best_correct:
                best_correct = new_max
                best_l = i + 1
                best_r = j + 1

    print(best_correct)
    print(best_l, best_r)

solve()
