    # Try pairs where the two letters are different
    for i in range(ord('a'), ord('z') + 1):
        for j in range(i + 1, ord('z') + 1):
            allowed_letters = {chr(i), chr(j)}
            current_total = sum(len(word) for word in words if is_valid(word, allowed_letters))
            max_total = max(max_total, current_total)

