import sys

def can_reach(E, a, k):
    total_available = 0.0
    total_needed = 0.0

    for ai in a:
        if ai > E:
            # Can transfer out (ai - E) units, but lose k%
            total_available += (ai - E) * (1 - k / 100)
        elif ai < E:
            # Need to receive (E - ai) units
            total_needed += (E - ai)

    return total_available >= total_needed

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Binary search on E
    left = 0.0
    right = sum(a) / n

    for _ in range(100):
        mid = (left + right) / 2
        if can_reach(mid, a, k):
            left = mid
        else:
            right = mid

    print(f"{left:.10f}")

if __name__ == "__main__":
    solve()
"}

