import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        W = int(next(it))
        widths = [int(next(it)) for _ in range(n)]

        # Count occurrences of each width
        count = {}
        max_width = 0
        for w in widths:
            count[w] = count.get(w, 0) + 1
            max_width = max(max_width, w)

        # Calculate max per row for each width
        max_per_row = {}
        for w in sorted(count.keys(), reverse=True):
            max_per_row[w] = W // w

        # Calculate total rows needed
        total_rows = 0
        for w in sorted(count.keys(), reverse=True):
            total_rows += (count[w] + max_per_row[w] - 1) // max_per_row[w]

        out_lines.append(str(total_rows))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

