def solve():
    data = []
    while True:
        try:
            line = input()
            if not line:
                break
            data.append(line)
        except EOFError:
            break

    n, m = map(int, data[0].split())

    # Parse all roads
    roads = []
    for i in range(1, m + 1):
        a, b, c = map(int, data[i].split())
        roads.append((a, b, c))

    # Create incidence matrix
    matrix = []
    for a, b, c in roads:
        row = [0] * (n + 1)  # cities are 1-indexed
        row[a] = 1
        row[b] = 1
        matrix.append(row)

    # Create augmented matrix for Gaussian elimination
    augmented = []
    for i in range(m):
        a, b, c = roads[i]
        row = [0] * (n + 1)
        row[a] = 1
        row[b] = 1
        row[m + i] = (1 - c) % 2  # target value
        augmented.append(row)

    # Perform Gaussian elimination over GF(2)
    rank = 0
    for col in range(n + 1):  # columns 1..n are cities, last m columns are variables
        pivot_row = -1
        for row in range(rank, m):
            if augmented[row][col] == 1:
                pivot_row = row
                break

        if pivot_row == -1:
            continue

        # Swap with rank row
        augmented[rank], augmented[pivot_row] = augmented[pivot_row], augmented[rank]

        # Eliminate this column in other rows
        for row in range(m):
            if row != rank and augmented[row][col] == 1:
                for col2 in range(col, n + m + 1):
                    augmented[row][col2] ^= augmented[rank][col2]

        rank += 1

    # Check if solution is possible
    for i in range(rank, m):
        if augmented[i][n + m] == 1:
            print("Impossible")
            return

    # Extract solution
    solution = [0] * (n + 1)  # cities 1..n
    for i in range(rank):
        # Find pivot column
        pivot_col = -1
        for j in range(n):
            if augmented[i][j] == 1:
                pivot_col = j
                break

        if pivot_col != -1:
            solution[pivot_col] = augmented[i][n + m]

    # Print solution
    cities = []
    for i in range(n):
        if solution[i + 1] == 1:
            cities.append(i + 1)

    print(len(cities))
    print(' '.join(map(str, cities)))

solve()
