import sys

def is_correct(s):
    """Check if a string of parentheses is a correct bracket sequence."""
    balance = 0
    for c in s:
        if c == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def solve() -> None:
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    s = data[1]

    # Find all divisors of n
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)

    # Try each divisor d = k+1
    max_beauty = 0
    best_l, best_r = 1, 1

    for d in sorted(divisors):
        length = n // d
        # Check if first length characters form a correct sequence
        if not is_correct(s[:length]):
            continue

        # Check if all subsequent blocks equal the first block
        valid = True
        for i in range(1, d):
            if s[i*length:(i+1)*length] != s[:length]:
                valid = False
                break

        if valid:
            max_beauty = d
            best_l = 1
            best_r = length
            # Try to find any position in the first block to swap
            # We can swap first '(' with first ')' in the first block
            # or swap two positions within the first block
            # Let's just swap first two characters in the first block
            if length >= 2:
                best_l, best_r = 1, 2
            else:
                best_l, best_r = 1, 1


    print(max_beauty)
    print(best_l, best_r)

if __name__ == "__main__":
    solve()
