    n = int(input())
    grid = []
    for _ in range(n):
        grid.append(input().strip())

    # Build bipartite graph: rows and columns
    # Rows: 0..n-1, Columns: n..2n-1
    # Edges: row i to column j if grid[i][j] == '.'

    graph = [[] for _ in range(2 * n)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                graph[i].append(n + j)

    # Ford-Fulkerson for maximum bipartite matching
    def bfs(start, end, prev):
        queue = [start]
        prev[start] = -1
        while queue:
            u = queue.pop(0)
            for v in graph[u]:
                if prev[v] == -1:
                    prev[v] = u
                    if v == end:
                        return True
                    queue.append(v)
        return False

    def ford_fulkerson(start, end):
        prev = [-1] * (2 * n)
        max_flow = 0
        while bfs(start, end, prev):
            path_flow = float('inf')
            v = end
            while prev[v] != -1:
                u = prev[v]
                path_flow = min(path_flow, 1)
                v = u
            max_flow += path_flow
            v = end
            while prev[v] != -1:
                u = prev[v]
                prev[v] = -1
                v = u
        return max_flow

    # Maximum matching
    max_matching = ford_fulkerson(0, 2 * n - 1)

    # Konig's theorem: minimum vertex cover = maximum matching
    # But we need to find the actual vertex cover
    # In bipartite graph, vertex cover can be found using max matching

    # Build residual graph
    residual = [[] for _ in range(2 * n)]
    for u in range(2 * n):
        for v in graph[u]:
            residual[u].append(v)

    # Find vertex cover
    # Using Konig's theorem: all vertices on one side with no augmenting path
    def has_augmenting_path(start, end):
        prev = [-1] * (2 * n)
        queue = [start]
        prev[start] = -1
        while queue:
            u = queue.pop(0)
            for v in residual[u]:
                if prev[v] == -1:
                    prev[v] = u
                    if v == end:
                        return True
                    queue.append(v)
        return False

    # Find minimum vertex cover
    def min_vertex_cover():
        # Find all vertices on one side with no augmenting path
        # from source to sink
        # In bipartite graph, we split into two partitions
        left = set(range(n))
        right = set(range(n, 2 * n))

