        idx += 1
        a = list(map(int, data[idx:idx + n]))
        idx += n

        result = []

        for k in range(1, n + 1):
            m = n - k + 1
            # Compute sliding minimum for window size k
            sliding = []
            min_deque = []

            for i in range(n):
                # Remove elements out of the current window
                while min_deque and min_deque[0] < i - k + 1:
                    min_deque.pop(0)

                # Remove elements larger than current element
                while min_deque and a[min_deque[-1]] >= a[i]:
                    min_deque.pop()

                min_deque.append(i)

                # When window is fully formed, add minimum
                if i >= k - 1:
                    sliding.append(a[min_deque[0]])

