def bpm(graph, u, match_to, visited):
    """Bipartite matching using DFS"""
    visited[u] = True
    for v in graph[u]:
        if match_to[v] == -1 or (not visited[match_to[v]] and bpm(graph, match_to[v], match_to, visited)):
            match_to[v] = u
            return True
    return False


def max_bipartite_matching(graph, n_left, n_right):
    """Find maximum bipartite matching"""
    match_to = [-1] * (n_right + 1)
    result = 0

    for u in range(1, n_left + 1):
        visited = [False] * (n_left + 1)
        if bpm(graph, u, match_to, visited):
            result += 1
    return match_to


def konigs_theorem(graph, match_to, n_left, n_right):
    """Find minimum vertex cover using Konig's theorem"""
    # Find all unmatched left vertices
    unmatched_left = [u for u in range(1, n_left + 1) if match_to[u] == -1]

    # BFS to find all right vertices reachable from unmatched_left via alternating paths
    visited = [False] * (n_right + 1)
    queue = deque()

    for u in unmatched_left:
        visited[u] = True
        queue.append(u)

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)

    # Minimum vertex cover: all left vertices not visited and all right vertices visited
    vertex_cover = []
    for u in range(1, n_left + 1):
        if not visited[u]:
            vertex_cover.append((u, -1))  # row
    for v in range(1, n_right + 1):
        if visited[v]:
            vertex_cover.append((-1, v))  # column

    return vertex_cover


