    """Bipartite matching using DFS"""
    visited[u] = True
    for v in graph[u]:
        if match_to[v] == -1 or (not visited[match_to[v]] and bpm(graph, match_to[v], match_to, visited)):
            match_to[v] = u
            return True
    return False


def max_bipartite_matching(graph, n_left, n_right):
    """Find maximum bipartite matching"""
    match_to = [-1] * (n_right + 1)
    result = 0

    for u in range(1, n_left + 1):
        visited = [False] * (n_left + 1)
        if bpm(graph, u, match_to, visited):
            result += 1
    return match_to


def konigs_theorem(graph, match_to, n_left, n_right):
    """Find minimum vertex cover using Konig's theorem"""
    # Find all unmatched left vertices
    unmatched_left = [u for u in range(1, n_left + 1) if match_to[u] == -1]

    # BFS to find all right vertices reachable from unmatched_left via alternating paths
    visited = [False] * (n_right + 1)
    queue = deque()

    for u in unmatched_left:
        visited[u] = True
        queue.append(u)

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)

    # Minimum vertex cover: all left vertices not visited and all right vertices visited
    vertex_cover = []
    for u in range(1, n_left + 1):
        if not visited[u]:
            vertex_cover.append((u, -1))  # row
    for v in range(1, n_right + 1):
        if visited[v]:
            vertex_cover.append((-1, v))  # column

    return vertex_cover


def solve():
    n = int(input().strip())
    grid = []
    for _ in range(n):
        grid.append(input().strip())

    # Build bipartite graph between rows and columns
    graph = [[] for _ in range(n + 1)]  # rows 1..n
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                graph[i + 1].append(j + 1)  # row i+1 can cover column j+1

    # Find maximum bipartite matching
    match_to = max_bipartite_matching(graph, n, n)

    # Find minimum vertex cover
    vertex_cover = konigs_theorem(graph, match_to, n, n)

    # Check if all rows and columns are covered
    covered_rows = set()
    covered_cols = set()

    for (u, v) in vertex_cover:
        if u != -1:
            covered_rows.add(u)
        if v != -1:
            covered_cols.add(v)

    # Check if all rows and columns are covered
    if len(covered_rows) != n or len(covered_cols) != n:
        print(-1)
    else:
        # Output the vertex cover as spells
        # But we need to output actual cells, not just rows/columns
        # Let's try a different approach: find a minimal set of cells that cover all rows and columns
        # This is the set cover problem, which is NP-hard, but we can try greedy

        # Build list of normal cells
        cells = []
        for i in range(n):
            for j in range(n):
                if grid[i][j] == '.':
                    cells.append((i + 1, j + 1))

        # Greedy set cover: always pick the cell that covers the most uncovered rows/columns
        selected = []
        covered_rows = set()
        covered_cols = set()

        while len(covered_rows) < n or len(covered_cols) < n:
            best = None
            max_cover = 0

            for cell in cells:
                if cell in selected:
                    continue

                i, j = cell
                row_cover = len(covered_rows.union([i]))
                col_cover = len(covered_cols.union([j]))

                if row_cover + col_cover > max_cover:
                    best = cell
                    max_cover = row_cover + col_cover

            if best is None:
                break

            selected.append(best)
            i, j = best
            covered_rows.add(i)
            covered_cols.add(j)

        if len(covered_rows) == n and len(covered_cols) == n:
            for (i, j) in selected:
                print(f"{i} {j}")
        else:
            print(-1)

