    for i in range(2, n + 1):
        adj[i].append((i + x) % n or n)

# Game states: 0 = Win, 1 = Lose, 2 = Loop
# dp[pos][turn] = state (0: Win, 1: Lose, 2: Loop)
dp = [[2] * 2 for _ in range(n + 1)]  # 0: Rick's turn, 1: Morty's turn

def solve(start_turn):
    """Determine game states for starting turn"""
    # Initialize states that directly lead to the black hole
    for pos in range(2, n + 1):
        if (pos + s1[0]) % n == 1 or (pos + s2[0]) % n == 1:
            # If current player can win immediately
            if start_turn == 0:
                dp[pos][0] = 0
            else:
