def solve_equation(equations):
    """Solve a system of linear equations over GF(2)"""
    n = len(equations[0])  # Number of variables
    m = len(equations)     # Number of equations

    # Gaussian elimination
    rank = 0
    for col in range(n):
        pivot = -1
        for row in range(rank, m):
            if (equations[row] >> col) & 1:
                pivot = row
                break

        if pivot == -1:
            continue  # No pivot in this column

        # Swap with the current rank row
        equations[rank], equations[pivot] = equations[pivot], equations[rank]

        # Eliminate this column from all other rows
        for row in range(m):
            if row != rank and ((equations[row] >> col) & 1):
                equations[row] ^= equations[rank]

        rank += 1

    # Check for inconsistency
    for row in range(rank, m):
        if equations[row] != 0:
            return None  # No solution

    # Back substitution
    solution = [0] * n
    for row in range(rank):
        # Find the pivot column
        pivot_col = -1
        for col in range(n):
            if (equations[row] >> col) & 1:
                pivot_col = col
                break

        if pivot_col == -1:
            continue

        # Check if the equation is consistent
        if equations[row] & (1 << pivot_col):
            solution[pivot_col] = 1

    return solution

n, m = map(int, input().split())
equations = []

for _ in range(m):
    u, v, c = map(int, input().split())
    u -= 1  # 0-indexed
    v -= 1

    # Create an equation: x_u + x_v = c (mod 2)
    # This means: x_u XOR x_v = c
    eq = 0
    eq |= (1 << u)
    eq |= (1 << v)

    equations.append(eq)

solution = solve_equation(equations)

if solution is None:
    print("Impossible")
else:
    # Count non-zero entries
    x = sum(solution)

    # Output the cities (1-indexed)
    print(x)
    for i in range(n):
        if solution[i]:
            print(i + 1, end=' ')
    print()
