adj = [[] for _ in range(n + 1)]
for _ in range(m):
    a, b = map(int, input().split())
    adj[a].append(b)
    adj[b].append(a)

visited = [False] * (n + 1)

# Check if a component is a clique
def is_clique(component):
    # component is a list of nodes in the same component
    # For each node, check if it's connected to all other nodes in the component
    for node in component:
        # Get all neighbors of node
        neighbors = adj[node]
        # Check if node is connected to all other nodes in the component
        for other in component:
            if other == node:
                continue
            if other not in neighbors:
                return False
    return True

# Find connected components and check if they are cliques
for start in range(1, n + 1):
    if not visited[start]:
        # BFS to find the entire component
        queue = [start]
        visited[start] = True
        component = [start]
        while queue:
            node = queue.pop(0)
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    component.append(neighbor)
                    queue.append(neighbor)

        # Check if this component is a clique
        if not is_clique(component):
            print("NO")
            exit()

print("YES")
