def solve():
    n, k = map(int, input().split())
    grid = [input().strip() for _ in range(n)]

    # dp[i][j][c] = lexicographically smallest string to reach (i, j) with exactly c changes
    INF = chr(ord('z') + 1)
    dp = [[[INF] * (k + 1) for _ in range(n)] for _ in range(n)]

    # Initialize starting cell
    dp[0][0][0] = grid[0][0]

    for i in range(n):
        for j in range(n):
            for c in range(k + 1):
                # If we're at the starting cell, skip
                if i == 0 and j == 0:
                    continue

                # Try coming from above
                if i > 0 and dp[i-1][j][c] != INF:
                    option1 = dp[i-1][j][c] + grid[i][j]
                    dp[i][j][c] = min(dp[i][j][c], option1)

                # Try coming from left
                if j > 0 and dp[i][j-1][c] != INF:
                    option2 = dp[i][j-1][c] + grid[i][j]
                    dp[i][j][c] = min(dp[i][j][c], option2)

                # Try changing the current cell (if we have changes left)
                for prev_c in range(c):
                    # From above with prev_c changes
                    if i > 0 and dp[i-1][j][prev_c] != INF:
                        # Change current character to the smallest possible
                        for new_char in 'abcdefghijklmnopqrstuvwxyz':
                            if new_char < grid[i][j]:
                                option3 = dp[i-1][j][prev_c] + new_char
                                dp[i][j][c] = min(dp[i][j][c], option3)

                    # From left with prev_c changes
                    if j > 0 and dp[i][j-1][prev_c] != INF:
                        for new_char in 'abcdefghijklmnopqrstuvwxyz':
                            if new_char < grid[i][j]:
                                option4 = dp[i][j-1][prev_c] + new_char
                                dp[i][j][c] = min(dp[i][j][c], option4)


    # Find the answer in the last cell with any number of changes up to k
    answer = min(dp[n-1][n-1][c] for c in range(k + 1))
    print(answer)

solve()
