def solve():
    n, k = map(int, input().split())
    grid = [input().strip() for _ in range(n)]

    # Priority queue: (string, i, j, changes_used)
    from heapq import heappush, heappop
    heap = []

    # Consider both options at the starting cell: keep current character or change it
    start_char = grid[0][0]
    heappush(heap, (start_char, 0, 0, 0))  # Keep 'y'

    if k > 0:
        for new_char in 'abcdefghijklmnopqrstuvwxyz':
            if new_char < start_char:
                new_s = new_char
                new_c = 1
                heappush(heap, (new_s, 0, 0, new_c))  # Change 'y' to a smaller character

    visited = set()

    while heap:
        s, i, j, c = heappop(heap)

        if i == n - 1 and j == n - 1:
            print(s)
            return

        if (i, j, c) in visited:
            continue

        visited.add((i, j, c))

        for di, dj in [(0, 1), (1, 0)]:
            ni, nj = i + di, j + dj
            if ni < n and nj < n:
                target_char = grid[ni][nj]

                if c <= k:
                    new_s = s + target_char
                    new_c = c
                    heappush(heap, (new_s, ni, nj, new_c))

                if c < k:
                    for new_char in 'abcdefghijklmnopqrstuvwxyz':
                        if new_char < target_char:
                            new_s = s + new_char
                            new_c = c + 1
                            heappush(heap, (new_s, ni, nj, new_c))

solve()
