def solve():
    t = int(input())
    for _ in range(t):
        n, x, m = map(int, input().split())
        # For each test case, build the operations
        operations = []
        for _ in range(m):
            l, r = map(int, input().split())
            operations.append((l, r))

        # We can use BFS where we track the current position and which operations have been used
        # But since m ≤ 100, we can use BFS with state (position, set of used operations)
        from collections import deque

        # To represent sets of operations, we'll use bitmasking
        # Since m ≤ 100, we need 100 bits, which can be represented as a Python int

        # Start at position x with no operations used
        visited = {}
        queue = deque()
        queue.append((x, 0))
        visited[(x, 0)] = True

        while queue:
            pos, mask = queue.popleft()

            # Try to use each unused operation
            for op_idx in range(m):
                if not (mask & (1 << op_idx)):
                    l, r = operations[op_idx]
                    # For this operation, we can swap any two positions in [l, r]
                    # So we can move the 1 from pos to any other position in [l, r]
                    if pos >= l and pos <= r:
