import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    M = int(data[1])

    # dp[i][j]: number of ways to turn on computers 1..i where the last manual turn is at position j
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: only one computer
    dp[1][1] = 1

    # Fill DP table
    for i in range(2, n + 1):
        for j in range(1, i + 1):
            # If we manually turn on computer i
            if j == i:
                # We can turn on computer i manually after turning on some previous configuration
                for k in range(1, i):
                    # Computer i-1 must be on if we turn on i manually
                    if dp[i-1][k] > 0 and (k == i-1 or dp[i-1][i-1] > 0):
                        dp[i][i] = (dp[i][i] + dp[i-1][k]) % M
            # If we manually turn on some other computer j
            # We need to consider all previous configurations
            for k in range(1, i):
                # Computer j must be on if we manually turn it on
                # Check if computer j-1 and j+1 are already on (if applicable)
                if j == 1:
                    # Computer 1 can be turned on manually if it's not already on
                    if dp[i-1][k] > 0:
                        dp[i][j] = (dp[i][j] + dp[i-1][k]) % M
                elif j == i:
                    # Computer i can be turned on manually if it's not already on
                    # Check if i-1 is on
                    if dp[i-1][k] > 0 and (k == i-1 or dp[i-1][i-1] > 0):
                        dp[i][j] = (dp[i][j] + dp[i-1][k]) % M
                else:
                    # Computer j can be turned on manually if it's not already on
                    # Check if j-1 and j+1 are on
                    if dp[i-1][k] > 0:
                        if (k == j-1 or dp[i-1][j-1] > 0) and (k == j+1 or dp[i-1][j+1] > 0):
                            dp[i][j] = (dp[i][j] + dp[i-1][k]) % M

    # The answer is dp[n][*] sum (all possible last manual turns)
    total = sum(dp[n][1:n+1]) % M

    print(total)

if __name__ == "__main__":
    solve()
