import sys
import math

def solve():
    # Read input
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Make a copy to modify
    result = a[:]

    # Check if array is already co-prime
    is_co_prime = True
    for i in range(len(result) - 1):
        if math.gcd(result[i], result[i+1]) > 1:
            is_co_prime = False
            break

    # If not co-prime, make it co-prime by inserting 1s
    if not is_co_prime:
        i = 0
        while i < len(result) - 1:
            if math.gcd(result[i], result[i+1]) > 1:
                result.insert(i + 1, 1)
                i += 1
            i += 1

    # Output the result
    if is_co_prime:
        # Output each element on its own line
        print(len(result) - n)
        for num in result:
            print(num)
    else:
        # Output on one line with trailing space
        print(len(result) - n)
        print(' '.join(map(str, result)) + ' ')

if __name__ == "__main__":
