        return 0

    # Get the largest "ones number" with the same number of digits as n
    digits = len(str(n))
    largest_ones_number = int("1" * digits)

    # Use as many of the largest "ones number" as possible
    count = 0
    while n > 0:
        if n >= largest_ones_number:
            n -= largest_ones_number
            count += digits
        else:
