def sieve(n):
    """Generate a list of prime numbers up to n using the Sieve of Eratosthenes."""
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return is_prime

def is_t_prime(x, is_prime):
    """Check if x is a T-prime."""
    sqrt_x = int(x ** 0.5)
    if sqrt_x * sqrt_x != x:
        return False
    return is_prime[sqrt_x]

def main():
    """Main function to read input and output results."""
    import sys
    input = sys.stdin.read().split()

    n = int(input[0])
    numbers = list(map(int, input[1:n+1]))

    max_val = int(10**6)  # Since 10^12's square root is 10^6
    is_prime = sieve(max_val)

    for x in numbers:
        if is_t_prime(x, is_prime):
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    main()
