import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    words = data[1:n+1]

    # For each possible pair of letters (including single letters)
    max_length = 0

    # Try all single letters
    for ch in range(ord('a'), ord('z') + 1):
        allowed = set([chr(ch)])
        total = 0
        for word in words:
            if all(c in allowed for c in word):
                total += len(word)
        max_length = max(max_length, total)

    # Try all pairs of letters
    for ch1 in range(ord('a'), ord('z') + 1):
        for ch2 in range(ch1 + 1, ord('z') + 1):
            allowed = set([chr(ch1), chr(ch2)])
            total = 0
            for word in words:
                if all(c in allowed for c in word):
                    total += len(word)
            max_length = max(max_length, total)

    print(max_length)

if __name__ == "__main__":
    solve()
